mapper.select:
SELECT r.reservation_id, r.member_no, r.branch_id, r.reserved_at, r.biz_type, r.purpose, r.status, r.created_at, r.updated_at, m.member_name, b.branch_name FROM TB_RESERVATION r JOIN TB_BANK_MEMBER m ON r.member_no = m.member_no JOIN TB_BRANCH b ON r.branch_id = b.branch_id
AND r.branch_id = #{branchId}
AND r.status = #{status}
AND TRUNC(r.reserved_at) = TO_DATE(#{date}, 'YYYY-MM-DD')
ORDER BY r.created_at DESC

mapper.update:
UPDATE TB_RESERVATION
   SET status     = #{afterStatus},
       updated_at = SYSDATE

         , branch_id   = #{newBranchId}


         , reserved_at = #{newReservedAt, jdbcType=TIMESTAMP}

 WHERE reservation_id = #{reservationId}
   AND status IN ('PENDING', 'CONFIRMED')
